/**
 * Database schema (section 8.1). Milestone-1 tables only; market, quests, clans and farming
 * tables arrive with their milestones. Ids are UUID v7 generated by the app; quantities and
 * coins are bigint; every bank/coin change goes through InventoryService and item_ledger.
 */
import { sql } from 'drizzle-orm';
import {
  bigint,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const accountMode = pgEnum('account_mode', ['normal', 'self_sufficient', 'hardcore']);
export const accountRole = pgEnum('account_role', ['player', 'admin']);
export const slotId = pgEnum('slot_id', ['main', 'secondary']);
export const equipSlot = pgEnum('equip_slot', [
  'head',
  'cape',
  'neck',
  'ammo',
  'weapon',
  'body',
  'shield',
  'legs',
  'hands',
  'feet',
  'ring',
  'tool',
]);
export const ledgerReason = pgEnum('ledger_reason', [
  'starter',
  'action',
  'combat',
  'death',
  'equip',
  'market',
  'shop',
  'admin',
]);

export const accounts = pgTable(
  'accounts',
  {
    id: uuid('id').primaryKey(),
    /** Stored lower-cased. */
    email: text('email').notNull(),
    passwordHash: text('password_hash').notNull(),
    mode: accountMode('mode').notNull().default('normal'),
    role: accountRole('role').notNull().default('player'),
    subscriptionUntil: timestamp('subscription_until', { withTimezone: true }),
    createdAt: createdAt(),
    bannedAt: timestamp('banned_at', { withTimezone: true }),
  },
  (t) => [uniqueIndex('accounts_email_key').on(t.email)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: uuid('id').primaryKey(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    /** SHA-256 of the session token (hex). The token itself is never stored. */
    tokenHash: text('token_hash').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    ip: text('ip'),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('sessions_token_hash_key').on(t.tokenHash),
    index('sessions_account_idx').on(t.accountId),
  ],
);

export const characters = pgTable(
  'characters',
  {
    id: uuid('id').primaryKey(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    regionId: text('region_id').notNull().default('brumaporto'),
    hp: integer('hp').notNull(),
    appearance: jsonb('appearance').notNull(),
    coins: bigint('coins', { mode: 'number' }).notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    // One character per account for now; dropping this index later allows more.
    uniqueIndex('characters_account_key').on(t.accountId),
    uniqueIndex('characters_name_key').on(sql`lower(${t.name})`),
    check('characters_coins_nonneg', sql`${t.coins} >= 0`),
  ],
);

const characterRef = () =>
  uuid('character_id')
    .notNull()
    .references(() => characters.id, { onDelete: 'cascade' });

export const skills = pgTable(
  'skills',
  {
    characterId: characterRef(),
    skillId: text('skill_id').notNull(),
    xpTenths: integer('xp_tenths').notNull().default(0),
    echoStars: smallint('echo_stars').notNull().default(0),
  },
  (t) => [
    primaryKey({ columns: [t.characterId, t.skillId] }),
    check('skills_xp_nonneg', sql`${t.xpTenths} >= 0`),
  ],
);

export const mastery = pgTable(
  'mastery',
  {
    characterId: characterRef(),
    actionId: text('action_id').notNull(),
    xp: integer('xp').notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.characterId, t.actionId] })],
);

export const slots = pgTable(
  'slots',
  {
    characterId: characterRef(),
    slot: slotId('slot').notNull(),
    /** Engine SlotState (JSON). */
    state: jsonb('state').notNull(),
    resolvedTick: integer('resolved_tick').notNull(),
    /** Seed words derived from (character, slot, restarts), stored as int32 (same bits as the uint32). */
    seed: integer('seed').array().notNull(),
    restarts: integer('restarts').notNull().default(0),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.characterId, t.slot] })],
);

export const bankItems = pgTable(
  'bank_items',
  {
    characterId: characterRef(),
    itemId: text('item_id').notNull(),
    qty: bigint('qty', { mode: 'number' }).notNull(),
    tab: smallint('tab').notNull().default(0),
  },
  (t) => [
    primaryKey({ columns: [t.characterId, t.itemId] }),
    check('bank_items_qty_pos', sql`${t.qty} > 0`),
  ],
);

export const equipment = pgTable(
  'equipment',
  {
    characterId: characterRef(),
    slot: equipSlot('slot').notNull(),
    itemId: text('item_id').notNull(),
  },
  (t) => [primaryKey({ columns: [t.characterId, t.slot] })],
);

export const bestiary = pgTable(
  'bestiary',
  {
    characterId: characterRef(),
    monsterId: text('monster_id').notNull(),
    kills: bigint('kills', { mode: 'number' }).notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.characterId, t.monsterId] })],
);

/** Audit of every bank item and coin movement. Coins use itemId "coins". */
export const itemLedger = pgTable(
  'item_ledger',
  {
    id: uuid('id').primaryKey(),
    characterId: characterRef(),
    itemId: text('item_id').notNull(),
    delta: bigint('delta', { mode: 'number' }).notNull(),
    reason: ledgerReason('reason').notNull(),
    refId: text('ref_id'),
    createdAt: createdAt(),
  },
  (t) => [
    index('item_ledger_character_item_idx').on(t.characterId, t.itemId),
    check('item_ledger_delta_nonzero', sql`${t.delta} <> 0`),
  ],
);

/** Game events for analytics and anti-cheat. */
export const eventLog = pgTable(
  'event_log',
  {
    id: uuid('id').primaryKey(),
    accountId: uuid('account_id').references(() => accounts.id, { onDelete: 'cascade' }),
    characterId: uuid('character_id').references(() => characters.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    data: jsonb('data').notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index('event_log_character_idx').on(t.characterId, t.createdAt)],
);
